document.addEventListener("DOMContentLoaded",()=>{const e={monsoon:{title:"Monsoon (Jul - Sep): Peak Discharge & Torrential Flow",desc:"The Kumaradhara River swells with intense rainfall from the Pushpagiri hills. Mist covers the gorge, creating an awe-inspiring tiered roar. Steps are slippery, and stepping into the river basin is strictly prohibited for safety.",flow:"Maximum (100%)",safety:"Caution (Leeches & Slippery Stairs)",vibe:"Majestic, Foggy & Intense"},"post-monsoon":{title:"Post-Monsoon (Oct - Dec): Ideal Clear Views & Moderate Flow",desc:"The skies clear over the Western Ghats while river discharge remains consistently full. Ideal for photography, trekking down the stairs, and bird watching around Pushpagiri.",flow:"High & Steady (75%)",safety:"Safe & Accessible",vibe:"Lush Green & Pleasant"},summer:{title:"Summer (Jan - May): Calm Thin Streams & Dry Boulders",desc:"The water volume drops significantly into narrow streams over the stone ledges. Allows clear exploration of the underlying volcanic geological stone structures.",flow:"Low (20%)",safety:"Very Safe",vibe:"Quiet & Rocky"}},t=document.querySelectorAll(".season-btn"),n=document.getElementById("season-title"),s=document.getElementById("season-desc"),a=document.querySelector(".season-stats");t.forEach(o=>{o.addEventListener("click",()=>{t.forEach(e=>e.classList.remove("active")),o.classList.add("active");const i=o.dataset.season,r=e[i];r&&n&&s&&a&&(n.textContent=r.title,s.textContent=r.desc,a.innerHTML=`\n          <span><strong>Flow Rate:</strong> ${r.flow}</span>\n          <span><strong>Trek Safety:</strong> ${r.safety}</span>\n          <span><strong>Vibe:</strong> ${r.vibe}</span>\n        `)})});const o=document.getElementById("falls-modal"),i=document.getElementById("modal-close"),r=document.getElementById("modal-title"),l=document.getElementById("modal-category"),d=document.getElementById("modal-description");function c(e,t,n){o&&(r.textContent=e,l.textContent=t||"Mallalli Falls Explorer",d.textContent=n,o.classList.add("active"),o.setAttribute("aria-hidden","false"))}function m(){o&&(o.classList.remove("active"),o.setAttribute("aria-hidden","true"))}document.querySelectorAll(".details-btn").forEach(e=>{e.addEventListener("click",()=>{c(e.dataset.title,e.dataset.category,e.dataset.description)})}),document.querySelectorAll(".gallery-item").forEach(e=>{e.addEventListener("click",()=>{c(e.dataset.title,"Gallery Preview",e.dataset.description)})}),i&&i.addEventListener("click",m),o&&o.addEventListener("click",e=>{e.target===o&&m()}),document.addEventListener("keydown",e=>{"Escape"===e.key&&o&&o.classList.contains("active")&&m()});const u=document.getElementById("btn-scroll-top");u&&(window.addEventListener("scroll",()=>{u.style.display=window.scrollY>300?"block":"none"}),u.addEventListener("click",()=>{window.scrollTo({top:0,behavior:"smooth"})}))});